import{_ as t,c as r,o as a,b0 as o}from"./chunks/framework.Dmsv_Tiv.js";const l="/media-docs/assets/image-20251204101255273.pjsyD8EV.png",i="data:image/png;base64,",A=JSON.parse('{"title":"LV035-RTSP简介","description":null,"frontmatter":{"title":"LV035-RTSP简介","date":"2025-12-03T10:29:07.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/transmission/126b19c468bb19dec8474a7f","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-03T10:29:07.413Z","fulluuid":"ec8474a7fa564c24abfdacb72e56f843","useduuid":"ec8474a7f"}},"headers":[],"relativePath":"sdoc/vcodec/transmission/126b19c468bb19dec8474a7f.md","filePath":"sdoc/20-视频编解码/10-视频传输/LV035-RTSP简介.md","lastUpdated":1767537778000}'),P={name:"sdoc/vcodec/transmission/126b19c468bb19dec8474a7f.md"};function n(d,e,T,R,s,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="lv035-rtsp简介" tabindex="-1">LV035-RTSP简介 <a class="header-anchor" href="#lv035-rtsp简介" aria-label="Permalink to &quot;LV035-RTSP简介&quot;">​</a></h1><h2 id="一、rtsp-简介" tabindex="-1">一、RTSP 简介 <a class="header-anchor" href="#一、rtsp-简介" aria-label="Permalink to &quot;一、RTSP 简介&quot;">​</a></h2><h3 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h3><p>RTSP 出现以前，最热的大概就是 HTTP 协议。想象一下，当你需要欣赏网络中的某一段视频，通过 HTTP 协议访问其 URL、开始下载、下载完成后播放。对于早期的视频采集设备、网络带宽或是负责渲染的显示器而言，似乎多给予一点耐心、多重连几次断开的 HTTP 连接、甚至多校验几次下载后文件的完整性，体验上也还能过得去。毕竟那时候的分辨率、帧率、带宽限制了互联网途径传播媒体文件的大小，信息的分享只能通过各种硬盘、U 盘、光盘以存储后文件的形式进行传输。</p><p>随着硬件设备技术的发展，采集设备分辨率在提升，显示器支持了更高的帧率，网络带宽也指数增长，这都为更好的观影体验提供了基础支持。随着网络资源的日益丰富，用户时间的稀缺性日益凸显，为了快速观看、判别视讯本身是否符合自身口味，在线实时观看成了一大诉求。而传统的 HTTP 下载显然不能够匹配该需求，因此在寻求 streaming 的道路上，RTSP 脱颖而出。</p><p>RTSP 全称实时流协议（Real Time Streaming Protocol），它是一个网络控制协议，设计用于娱乐、会议系统中控制流媒体服务器。RTSP 用于在希望通讯的两端建立并控制媒体会话（session），客户端通过发出 VCR-style 命令如 play、record 和 pause 等来实时控制媒体流。</p><h3 id="_2-简介" tabindex="-1">2. 简介 <a class="header-anchor" href="#_2-简介" aria-label="Permalink to &quot;2. 简介&quot;">​</a></h3><p>RTSP(Real-Time Stream Protocol)是一种基于文本的应用层协议，在语法及一些消息参数等方面，<strong>RTSP 协议与 HTTP 协议类似</strong>。是 TCP/IP 协议体系中的一个应用层协议, 由哥伦比亚大学, 网景和 RealNetworks 公司提交的 IETF RFC 标准。</p><p>该协议定义了一对多应用程序如何有效地通过 IP 网络传送多媒体数据。RTSP 在体系结构上位于 RTP 和 RTCP 之上, 它使用 TCP 或 RTP 完成数据传输。RTSP 被用于建立的控制媒体流的传输，它为多媒体服务扮演“网络远程控制”的角色。尽管有时可以把 RTSP 控制信息和媒体数据流交织在一起传送，但一般情况 RTSP 本身并不用于转送媒体流数据。媒体数据的传送可通过 RTP/RTCP 等协议来完成。</p><blockquote><p><a href="https://datatracker.ietf.org/doc/html/rfc2326" target="_blank" rel="noreferrer">RFC 2326 - Real Time Streaming Protocol (RTSP)</a></p><p><a href="https://raw.gitcode.com/Open-source-documentation-tutorial/f52e6/raw/main/RTSP%E5%8D%8F%E8%AE%AE%E8%AF%A6%E7%BB%86%E6%8F%8F%E8%BF%B0(%E4%B8%AD%E6%96%87%E7%89%88)-rfc2326.pdf" target="_blank" rel="noreferrer">RTSP 协议详细描述(中文版)</a></p></blockquote><h3 id="_3-一次-rtsp-操作的过程" tabindex="-1">3. 一次 RTSP 操作的过程 <a class="header-anchor" href="#_3-一次-rtsp-操作的过程" aria-label="Permalink to &quot;3. 一次 RTSP 操作的过程&quot;">​</a></h3><ul><li>首先，客户端连接到流服务器并发送一个 RTSP 描述命令（DESCRIBE）。</li><li>流服务器通过一个 SDP（会话描述协议，Session Description Protocol） 描述来进行反馈，反馈信息包括流数量、媒体类型等信息。</li><li>客户端再分析该 SDP 描述，并为会话中的每一个流发送一个 RTSP 建立命令(SETUP)，RTSP 建立命令告诉服务器客户端用于接收媒体数据的端口。流媒体连接建立完成后，</li><li>客户端发送一个播放命令(PLAY)，服务器就开始在 UDP 上传送媒体流（RTP 包）到客户端。在播放过程中客户端还可以向服务器发送命令来控制快进、快退和暂停等。</li><li>最后，客户端可发送一个终止命令(TERADOWN)来结束流媒体会话</li></ul><h2 id="二、rtsp-over-udp-tcp" tabindex="-1">二、RTSP over UDP/TCP <a class="header-anchor" href="#二、rtsp-over-udp-tcp" aria-label="Permalink to &quot;二、RTSP over UDP/TCP&quot;">​</a></h2><p>播放 RTSP 流时，可通过客户端来指定拉流方式为 UDP 还是 TCP。其实吧，个人觉得应该是客户端通过 RTSP 决定使用 UDP 还是 TCP 来传输后续的 RTP 包和 RTCP 包，而不是 RTSP 是使用 UDP/TCP，RTSP 走的只有 TCP 而已，这里简单说明一下。</p><p><img src="'+l+'" alt="image-20251204101255273"></p><p>RTSP over TCP 方式时，RTSP、RTP(Video)、RTCP(Video)、RTP(Audio)、RTCP(Audio)都通过同一个 TCP 连接来传输。那么如何区分 RTSP、RTP(Video)、RTCP(Video)、RTP(Audio)、RTCP(Audio) ？做法是对于 RTP 和 RTCP 包，在 TCP 和 RTP（RTCP）数据之间增加一层 RTSP Interleaved Frame，如下所示。</p><p><img src="'+i+'" alt="image-20251204101912714"></p><ul><li><p>dollar sign : 魔数，美元符号 <code>$ (0x24)</code> 用于表明 Interleave Frame 层的开始</p></li><li><p>channel identifier：表明协议的类型一般如下:</p></li></ul><table><tr><td align="center">0x00</td><td align="center">Video RTP</td></tr><tr><td align="center">0x01</td><td align="center">Video RTCP</td></tr><tr><td align="center">0x02</td><td align="center">Audio RTP</td></tr><tr><td align="center">0x03</td><td align="center">Audio RTCP</td></tr></table><ul><li>data length：RTP 包(封装的二进制数据)的大小</li></ul><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/m0_73443478/article/details/137231316" target="_blank" rel="noreferrer">rtsp 协议详解-最详细的流媒体传输协议-CSDN 博客</a></p><p><a href="https://blog.csdn.net/yhb1206/article/details/143222329" target="_blank" rel="noreferrer">rtsp 的 2 种收流模式_rtp over rtsp-CSDN 博客</a></p><p><a href="https://developer.aliyun.com/article/1472301" target="_blank" rel="noreferrer">深入解析 RTP RTCP 协议报文结构与抓包分析-开发者社区-阿里云</a></p><p><a href="https://www.cnblogs.com/iFrank/p/15434438.html" target="_blank" rel="noreferrer">【rtp over tcp/rtsp 解析】&amp;&amp;【H264 格式与 RTP 包解析】&amp;&amp;【以 H264 的打包方式-分片打包(type = 28 FU-A 方式为例)】</a></p><p><a href="https://blog.csdn.net/luyumiao1990/article/details/106093001" target="_blank" rel="noreferrer">RTSP over UDP 与 RTSP over TCP 取流对比_rtp over udp-CSDN 博客</a></p></blockquote>',21)])])}const f=t(P,[["render",n]]);export{A as __pageData,f as default};
